def div(x):
	if x == 16 or x == 34 or x == 289:
		return 'Tom'
	elif x == 17 or x & 1 == 0:
		return 'Mike'
	else:
		t = int(x ** 0.5)
		for i in range(3, t + 1, 2):
			if x % i == 0:
				return 'Mike'
		return 'Tom'
for v in range(int(input())):
